import pytest
from store import InMemoryStore


@pytest.fixture
def store():
    return InMemoryStore()


# --- set / get ---

def test_set_and_get(store):
    store.set("a", 1)
    assert store.get("a") == 1


def test_get_default_when_missing(store):
    assert store.get("nope") is None


def test_get_custom_default(store):
    assert store.get("nope", 42) == 42


def test_overwrite(store):
    store.set("k", "first")
    store.set("k", "second")
    assert store.get("k") == "second"


# --- delete ---

def test_delete_existing(store):
    store.set("x", 10)
    assert store.delete("x") is True
    assert store.get("x") is None


def test_delete_nonexistent(store):
    assert store.delete("nope") is False


# --- has ---

def test_has_present(store):
    store.set("present", True)
    assert store.has("present") is True


def test_has_missing(store):
    assert store.has("missing") is False


def test_has_after_delete(store):
    store.set("gone", 1)
    store.delete("gone")
    assert store.has("gone") is False


# --- keys ---

def test_keys_empty(store):
    assert list(store.keys()) == []


def test_keys_after_sets(store):
    store.set("b", 2)
    store.set("a", 1)
    assert sorted(store.keys()) == ["a", "b"]


def test_keys_after_delete(store):
    store.set("a", 1)
    store.set("b", 2)
    store.delete("a")
    assert list(store.keys()) == ["b"]
